<template>
  <div><Navbar/><main class="shell cart-page">
    <header><span>YOUR BAG</span><h1>Shopping cart</h1><p>{{ count }} {{ count===1?'item':'items' }} in your bag</p></header>
    <div v-if="error" class="notice error" role="alert">{{ error }} <button @click="clearError">Dismiss</button></div>
    <section v-if="!items.length&&!loading" class="empty"><span>□</span><h2>Your bag is ready for a fresh find</h2><p>Browse the edit and add anything you would like to keep.</p><router-link to="/browse">Discover products</router-link></section>
    <div v-else class="layout">
      <section class="items">
        <div class="selection"><label><input type="checkbox" :checked="selectedCount===items.length" @change="selectAll($event.target.checked)"> Select all</label><button :disabled="!selectedCount" @click="removeSelected">Remove selected</button></div>
        <article v-for="item in items" :key="item.id||item.product_id" :class="{muted:!selectedIds.includes(item.product_id)}">
          <input type="checkbox" :checked="selectedIds.includes(item.product_id)" :aria-label="`Select ${title(item)}`" @change="toggleSelect(item.product_id)">
          <router-link :to="`/products/${item.product?.slug}`" class="image"><img v-if="item.product?.images?.[0]" :src="item.product.images[0].thumbnail_url||item.product.images[0].image_url" :alt="title(item)"></router-link>
          <div class="details"><span>{{ item.product?.brand||'CURATED FIND' }}</span><router-link :to="`/products/${item.product?.slug}`">{{ title(item) }}</router-link><small>{{ condition(item.product?.condition_grade) }} · {{ modeLabel(item) }}</small><button @click="removeFromCart(id(item))">Remove</button></div>
          <div class="quantity"><button :disabled="isPending(item.product_id)||item.quantity<=1" @click="change(item,item.quantity-1)">−</button><span>{{ item.quantity }}</span><button :disabled="isPending(item.product_id)" @click="change(item,item.quantity+1)">+</button></div><strong>€{{ money(Number(item.product?.sale_price)*item.quantity) }}</strong>
        </article>
      </section>
      <aside>
        <span>ORDER SUMMARY</span><h2>{{ selectedUnits }} selected</h2>
        <div v-if="mixedModes" class="mode-warning"><strong>Separate orders required</strong><p>Online delivery and face-to-face products cannot share one order. Uncheck one transaction type to continue.</p></div>
        <div class="row"><em>Subtotal</em><strong>€{{ money(selectedTotal) }}</strong></div>
        <div class="row"><em>{{ mixedModes?'Fulfilment':selectedMode==='in_person'?'Collection':'Estimated delivery' }}</em><strong>{{ mixedModes?'Separate orders':selectedMode==='in_person'?'At meetup':shippingLoading?'…':shippingError?'At checkout':`€${money(shippingTotal)}` }}</strong></div>
        <div v-if="promotion" class="row discount"><em>{{ promotion.label||promoCode }}</em><strong>−€{{ money(promotion.discount_amount) }}</strong></div>
        <form class="promo" @submit.prevent="applyPromo"><label for="promo">Promotion code</label><div><input id="promo" v-model.trim="promoCode" placeholder="Enter code"><button :disabled="promoLoading">Apply</button></div><p v-if="promoMessage" :class="{error:promoError}">{{ promoMessage }}</p></form>
        <div class="total"><span>Estimated total</span><strong>€{{ money(estimatedTotal) }}</strong></div><p>{{ mixedModes?'Uncheck one transaction type to continue.':selectedMode==='in_person'?'The item is reserved for 48 hours. Pay only when you meet and inspect it.':'Tax is included where applicable. Final delivery is confirmed by the server at checkout.' }}</p>
        <button class="checkout-main" :disabled="!canCheckout" @click="beginCheckout">{{ !selectedCount?'Select an item':mixedModes?'Separate orders required':selectedMode==='in_person'?'Reserve meetup':'Secure checkout' }} <b>→</b></button>
        <div class="security">{{ mixedModes?'Delivery and meetup require separate orders':selectedMode==='in_person'?'✓ Contact shared after reservation':'✓ Secure payment · Buyer protection' }}</div>
      </aside>
    </div>
  </main><Footer/></div>
</template>
<script setup>
import { computed,onMounted,ref,watch } from 'vue';import { useRouter } from 'vue-router';import Navbar from '../components/Navbar.vue';import Footer from '../components/Footer.vue';import { getCartShippingEstimate,validatePromotion } from '../api';import { useCart } from '../composables/useCart';import { useLocation } from '../composables/useLocation'
const router=useRouter();const {items,count,loading,error,selectedIds,selectedItems,selectedCount,selectedUnits,selectedTotal,updateQty,removeFromCart,removeSelected,toggleSelect,selectAll,clearError,isPending,fetchServer}=useCart();const {countryCode,initLocation}=useLocation();const shippingLoading=ref(false),shippingTotal=ref(0),shippingError=ref(''),promoCode=ref(sessionStorage.getItem('esh_promo_code')||''),promotion=ref(null),promoLoading=ref(false),promoMessage=ref(''),promoError=ref(false)
const itemMode=item=>item.product?.transaction_mode||'online';const selectedModes=computed(()=>[...new Set(selectedItems.value.map(itemMode))]);const mixedModes=computed(()=>selectedModes.value.length>1);const selectedMode=computed(()=>selectedModes.value[0]||'online');const canCheckout=computed(()=>selectedCount.value>0&&!mixedModes.value);const estimatedTotal=computed(()=>Math.max(0,Number(selectedTotal.value)-Number(promotion.value?.discount_amount||0)+(selectedMode.value==='online'?Number(shippingTotal.value):0)));const money=v=>Number(v||0).toFixed(2),id=item=>item.id||item.product_id,title=item=>item.product?.title_en||item.product?.title||'Product';const condition=v=>({new:'New',like_new:'Like new',good:'Good',fair:'Fair',poor:'Well loved',for_parts:'For parts'}[v]||'Pre-loved');const modeLabel=item=>itemMode(item)==='in_person'?'Meetup only':'Online payment';const beginCheckout=()=>{if(!canCheckout.value)return;router.push({path:'/checkout',query:{mode:selectedMode.value}})}
async function change(item,qty){try{await updateQty(id(item),qty)}catch{}}async function loadShipping(){const onlineItems=selectedItems.value.filter(item=>itemMode(item)==='online');if(!countryCode.value||!onlineItems.length){shippingTotal.value=0;shippingError.value='';return}shippingLoading.value=true;shippingError.value='';try{const {data}=await getCartShippingEstimate(countryCode.value,onlineItems.map(i=>i.product_id));shippingTotal.value=Number(data.shipping_total||0)}catch(e){shippingError.value=e.response?.data?.detail||'Delivery calculated at checkout';shippingTotal.value=0}finally{shippingLoading.value=false}}
async function applyPromo(){promoLoading.value=true;promoMessage.value='';promoError.value=false;try{const {data}=await validatePromotion(promoCode.value,selectedTotal.value);promotion.value=data;sessionStorage.setItem('esh_promo_code',promoCode.value);promoMessage.value=data.label||'Promotion applied'}catch(e){promotion.value=null;sessionStorage.removeItem('esh_promo_code');promoError.value=true;promoMessage.value=e.response?.data?.detail||'This code is not available.'}finally{promoLoading.value=false}}
watch([selectedItems,countryCode],loadShipping,{deep:true});watch(selectedTotal,()=>{if(promotion.value)applyPromo()});onMounted(async()=>{await Promise.all([initLocation(),fetchServer({silent:true})]);await loadShipping();if(promoCode.value)applyPromo()})
</script>
