,serif}.row{display:flex;justify-content:space-between;padding:8px 0;color:#617068;font-size:11px}.row em{font-style:normal}.row strong{color:#173f34}.row.discount,.row.discount strong{color:#4e744f}.promo{margin:16px 0;padding:15px 0;border-block:1px solid #e2e7e1}.promo label{font-size:10px;font-weight:800}.promo>div{display:flex;margin-top:7px}.promo input{min-width:0;flex:1;height:42px;border:1px solid #d4dbd4;border-radius:10px 0 0 10px;padding:0 10px}.promo button{border:0;border-radius:0 10px 10px 0;background:#e5ef8a;color:#173f34;padding:0 14px;font-size:10px;font-weight:900}.promo p{margin:7px 0 0;color:#4f744f;font-size:9px}.promo p.error{color:#9a493c}.total{display:flex;justify-content:space-between;align-items:end;padding-top:8px}.total span{font-size:12px;font-weight:850}.total strong{font:700 29px Georgia,serif}.layout>aside>p{color:#748078;font-size:9px;line-height:1.5}.checkout-main{display:flex;width:100%;min-height:52px;justify-content:space-between;align-items:center;margin-top:18px;padding:0 19px;border:0;border-radius:999px;background:#173f34;color:white;font-size:12px;font-weight:850}.checkout-main:disabled{background:#a5afa9}.security{margin-top:13px;text-align:center;color:#6c7973;font-size:9px}.empty{margin-top:35px;padding:75px 25px;text-align:center}.empty>span{font-size:44px}.empty h2{font:700 29px Georgia,serif}.empty p{color:#6c7a73;font-size:12px}.empty a{display:inline-flex;margin-top:12px;border-radius:999px;background:#173f34;color:white;padding:14px 20px;font-size:11px;font-weight:850}.notice{margin-top:20px;padding:12px 15px;border-radius:12px;background:#fff0e8;color:#8b4736;font-size:11px}.notice button{float:right;border:0;background:transparent;text-decoration:underline}@media(max-width:850px){.shell{width:min(100% - 28px,1180px)}.layout{grid-template-columns:1fr}.layout>aside{position:static}.items article{grid-template-columns:20px 82px 1fr auto}.image{width:82px;height:96px}.quantity{grid-column:3}.items article>strong{grid-column:4;grid-row:1/3}}@media(max-width:520px){.cart-page h1{font-size:39px}.items article{grid-template-columns:18px 72px 1fr}.image{width:72px;height:88px}.quantity{grid-column:3}.items article>strong{grid-column:3;grid-row:auto}.details>a{font-size:15px}}</style>
